import json
import re

def is_private_ip(ip):
    if not ip:
        return False
    if '.' in ip:
        try:
            parts = ip.split('.')
            if len(parts) == 4:
                octets = [int(p) for p in parts]
                if octets[0] == 10:
                    return True
                if octets[0] == 172 and 16 <= octets[1] <= 31:
                    return True
                if octets[0] == 192 and octets[1] == 168:
                    return True
        except ValueError:
            pass
    return False

with open('/workdir/normalized.json') as f:
    data = json.load(f)
    all_private_involvement = True
    for r in data:
        src_priv = is_private_ip(r['src_ip'])
        dst_priv = is_private_ip(r['dst_ip'])
        if not src_priv and not dst_priv:
            print("Found record with no private IPs:", r)
            all_private_involvement = False
    print("All records involve private IPs:", all_private_involvement)
EOF"}

