required_fields = ["timestamp", "src_ip", "dst_ip", "protocol", "action", "port"]
for i, item in enumerate(data):
    for field in required_fields:
        if field not in item:
            print(f"  Item {i} missing field: {field}")
    # Check types
    if not isinstance(item["timestamp"], str):
        print(f"  Item {i} timestamp not string")
    if not isinstance(item["src_ip"], str):
        print(f"  Item {i} src_ip not string")
    if not isinstance(item["dst_ip"], str):
        print(f"  Item {i} dst_ip not string")
    if not isinstance(item["protocol"], str) or item["protocol"] not in ["tcp", "udp"]:
        print(f"  Item {i} protocol invalid: {item['protocol']}")
    if not isinstance(item["action"], str) or item["action"] not in ["allow", "deny", "drop", "reset"]:
        print(f"  Item {i} action invalid: {item['action']}")
    port = item["port"]
    if port is not None and not isinstance(port, int):
        print(f"  Item {i} port not int or null: {port}")
    # Check timestamp format ISO8601 with Z
    if not item["timestamp"].endswith("Z"):
        print(f"  Item {i} timestamp doesn't end with Z: {item['timestamp']}")

print("All validations passed!")
